  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (291::BIGINT, 'Un grosero profesor arrogante. Explica mal y anda jugando de conocedor con paja que sale de su boca. La excelencia que "pide" no es más que una excusa por no saber enseñar y exigir más de lo que sabe dar. De los peores profesores del TEC en mi opinión.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-08-27T00:00:00+00:00'::TIMESTAMPTZ, 'b3691392a9d384a3a445148c9804fd750f737b991a6d5037068efba89cdafe66'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'No le crean a los que dicen que es un buen profe, pasé por esfuerzo y merito mío. Un maleducado, machista y egocéntrico. Métodos de aprendizaje que ya no se usan todo en físico y nada virtual... un profesor de Compu que no le gusta la tecnología, además les pide un cuaderno forrado todo pura tusa.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2026-07-10T00:00:00+00:00'::TIMESTAMPTZ, 'b5662b018261725edca7a4a91605ea4b83e7dc993ddfbe4465728dd8e199f431'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'Es uno de los mejores profes para mí del TEC. Sus métodos de aprendizaje aunque parezcan raros, son los mitos que me decían de lo que iba a ser universidad. Te hace aprender a fuerza, y si se esfuerza puede llegar a tener buena nota, lleve con él si quiere aprender un montón.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Exámenes retadores']::TEXT[], '2026-06-24T00:00:00+00:00'::TIMESTAMPTZ, '4eda26356b691a944f13b14703e4a2610c7e54ce5e648cdfc7c9e95b2e27ecf2'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'Profesor ofensivo y grosero con los estudiantes. Hay que llevar un cuadernillo forrado, parece un profesor de escuela con conocimientos viejos No sabe o no entiende nada de clases virtuales. Evítelo a toda costa, con cualquier otro profesor va a aprender más.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-05-24T00:00:00+00:00'::TIMESTAMPTZ, '5b7ffd10606e63f0e17def5c84230286ed9983f498319cec1f055b50ce34eb1d'::TEXT, ARRAY[1151]::BIGINT[]),
    (291::BIGINT, 'De los mejores profesores del tecnológico sin lugar a dudas, explica muy claro. Hace quices semanales pasables si le pones atención a las clases. Para los que se quejan del cuaderno y de la forma de ser del profe, no sean tan vagabundos ni delicados, o váyanse a la ULACIT.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2026-04-20T00:00:00+00:00'::TIMESTAMPTZ, '9ec3c1940d7783181e9702357c3006488edf31a73e28f228261dd9e9804bfb42'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'Aunque a muchos no les cae bien, es de los mejores profes del TEC. Explica bien, deja proyectos pesados, es de los pocos profes con los que uno realmente aprende. A pesar de sus particularidades (talvez gracias a), sus clases son interesantes e interactivas. Matricule con él si quiere aprender.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-03-08T00:00:00+00:00'::TIMESTAMPTZ, '0b191c8a6477d175bed5fc4b320397e37442bfc40dbcc1088a484e94e88c021c'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'Me asustaba los malos comentarios pero realmente aprendí un monton, es un profesor muy particular pero si usted le pone va a pasar bien, 3 exámenes, quiz cada semana, da puntos extra, en general mejor que otros profes de la carrera, lo recomiendo porque si se aprende de verdad y si es pasable.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Clases largas']::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'f1155e9150a033e2dd3e61614b122edbce5a4440280183d8236cb1635d1f2fb6'::TEXT, ARRAY[1151]::BIGINT[]),
    (291::BIGINT, 'Pésimo profesor. Está 40 años atrás. Lo obliga a uno a tener un cuadernito forrado como si fuera una clase de escuela. Evítelo a toda costa.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-11-27T00:00:00+00:00'::TIMESTAMPTZ, '38d2c7dab539e252102c4c15b0273957e93f9ba181099ad0ba413e3496e27835'::TEXT, ARRAY[1151]::BIGINT[]),
    (291::BIGINT, 'Profesor grosero y ofensivo con los estudiantes. Sus conocimientos son muy antiguos. Que mal que en el TEC todavía queden profesores así.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura']::TEXT[], '2025-10-19T00:00:00+00:00'::TIMESTAMPTZ, '2088e125f0ecf4bebc9b9d69842837b8fca9de58c30c1747ffab432ef743233d'::TEXT, ARRAY[1017]::BIGINT[]),
    (291::BIGINT, 'Un profesor que si pudiera programar en Cobol en una computadora con Windows 98 lo haría. Es increíble que el TEC siendo la mejor U de ingeniería tenga profesores que se quedaron en la prehistoria y no se actualicen.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-08-28T00:00:00+00:00'::TIMESTAMPTZ, 'c5a7a961848a259c320608d101fe652d50b7e73dd7f73de61ba6eb85040804fe'::TEXT, ARRAY[337]::BIGINT[]),
    (291::BIGINT, 'Pésimo profe. No sé ni qué decir. Cualquier otro profesor le va a enseñar más que Torres.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2025-07-27T00:00:00+00:00'::TIMESTAMPTZ, '61a8668a381bf28e3d6cf468d276f2fda733b1b000c42c78b3b41a718978eea9'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'El peor de lo peor. No ayuda en nada, solo hace ejemplos sencillos pero deja trabajos y exámenes difíciles. No le gustan las clases virtuales. Parece un profesor de hace 40 años atrás.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-05-16T00:00:00+00:00'::TIMESTAMPTZ, '0a427096e041c7d0a7ea2625cf3d5a9167c61ae60782c088257a106326b45f5c'::TEXT, ARRAY[337]::BIGINT[]),
    (291::BIGINT, 'Me parece increíble los comentarios negativos, yo que he llevado clases en distinto lugares, para mí ha sido uno de los mejores profesores de vida.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-04-04T00:00:00+00:00'::TIMESTAMPTZ, '9e85f8bcc8d4b89216b1eb7efbf0b622246253d4f743bfb49b8a49e32113301f'::TEXT, ARRAY[337]::BIGINT[]),
    (291::BIGINT, 'Muy mal profe, no ayuda en nada y es bastante pesado. Cuesta mucho que responda las consultas que se le hacen.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'a38d22d129353fca6c621a1bf288fae8a54048b0279be679dc9cb0521e65710e'::TEXT, ARRAY[1017]::BIGINT[]),
    (291::BIGINT, 'Es un profesor difícil de llevar, tiene un carácter serio y cómico, pero con un humor difícil de llevar para algunas personas. En la materia explica bastante bien, hace quices todas las semanas y los exámenes son pesados en materia. Es buen profe, si se sabe adaptar a su manera se aprenden mucho.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Muchos exámenes']::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'b5492c5fc7bd71869a4e3431447f49e09ab966ef9fca992e48c5793aee43ab90'::TEXT, ARRAY[1017]::BIGINT[]),
    (291::BIGINT, 'Super malo como profe y como persona. No ayuda en nada. Ah pero cada clase te recuerda que él es un "doctor".'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2024-09-25T00:00:00+00:00'::TIMESTAMPTZ, 'f0dc7ac34ef0aad495d0977c0dd34dedbd7b1e511ee6b3f0f2255d4278b95382'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'Es un profesor excelente al que le agarras cariño, las clases las explica fenomenalmente y te hace que tengas interes en lo que él enseña. Cada semana tienes que hacer quiz (tenes que prepararte, porque algunos son de ejemplos no vistos en clase) Examenes faciles y los trabajos son muy largos.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'd939b4704510055943c825bb77bcfa7ba67e9b188d6fc289d9d3a8ec3f998fb8'::TEXT, ARRAY[1017]::BIGINT[]),
    (291::BIGINT, 'El profe explica bastante bien, sin embargo, el curso es muyyy difícil. Los proyectos son largos y complejos, al igual que los exámenes. Hay quices todas las semanas.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '62ba31ea653867726ba97270a7395cb7eff6e6741599ade78b489b464e481392'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Peor profe que hay en todo el TEC. Si quiere aprender, no perder el tiempo y no perder el curso, mejor matricule con cualquier otro.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2024-01-13T00:00:00+00:00'::TIMESTAMPTZ, 'f199cb3746f23a2676252b8e1730ebe11decfdb7b8791aae36012648ee08e406'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'El peor profe del TEC, no entrega notas, no ayuda al estudiante, pero se la pasa diciendo que el mejor profe del TEC. El cree que sabe mucho pero no sabe enseñar nada. Evitese el problema, matricule con otro profesor.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2023-11-12T00:00:00+00:00'::TIMESTAMPTZ, '0a8340520ec3a1e5b686375d78daed7c2407b291f4289e5ff10d73d611c5f714'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'Pésimo profe, no entrega notas hasta el final, no ayuda al estudiante, pero se la pasa diciendo que el mejor profe del TEC.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'bcd821441e4d2f00ad3ccc42c945c0f8a45cd716a668538ffbeb7e36fc755bcd'::TEXT, ARRAY[1151]::BIGINT[]),
    (291::BIGINT, 'Semana 19 y este hp no ha subido una sola calificación, no da feedback, no da buenas clases, nada, ahhhhh pero para jugar de intrépido con su título se PhD es buenísimo el inútil este... Un profesor que prácticamente se está robando el salario...'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '257acac146d193e6e3a3ce4e659033d05d91db8d4b44dee071aa2e9027a627cd'::TEXT, ARRAY[1151]::BIGINT[]),
    (291::BIGINT, 'De lo peorcito, este roco piensa que dejar tareas exorbitantes y proyectos larguisimos es ser profesor, las clases son una perdida de tiempo, preguntarle es una perdida de tiempo, con este mae todo es una perdida de tiempo.Que se meta su título por donde ya sabe...'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'ca508dc007df1c5d8c40a9e7139b39b23166b019bff3b6e42cb3e04686d66212'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'El profesor no enseña nada, hay que estudiar todo solo. A él solo le gusta que vean que es un PD. Pésimo curso.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2023-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'b187a863f31ac017710b5eeaaf0c751375bf25645662fb5a1b041bbac5dc6bb1'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'Los buenos comentarios son prácticamente "el profe es un explotador pero con el poder del amor todo es posible" compas en serio, que un profesor no respete la cantidad de créditos y creo que su curso es el único lo hace únicamente un maldito. PD: el mae no enseña nada, ud aprende solo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-20T00:00:00+00:00'::TIMESTAMPTZ, 'ab09b3dcdb573d201e9e6b3d36c4b1b690664d36155fe526b48f2080a098e703'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'Un profesore excelente, de los mejores que he tenido en la carrera, sus clases son excelentes, aunque *SUMAMENTE EXIGENTES*. Es muy importante tomar buenos apuntes, cuando dice que puede preguntar lo que quiera es porque pregunta de todo. Todas las semanas hay quiz'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2022-12-09T00:00:00+00:00'::TIMESTAMPTZ, '37bd273575b92e64db43403211b490f73089962adf29390ac21e7655df0f1acf'::TEXT, ARRAY[1017]::BIGINT[]),
    (291::BIGINT, 'Es un curso bastante teórico, por lo que hay que estudiar constantemente ya que hace quices todas las semanas. Deja aproximadamente 5 proyectos programados y las tareas son mas teóricas. Los exámenes son muy difíciles, pero nada imposible :)'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Exámenes retadores']::TEXT[], '2022-12-07T00:00:00+00:00'::TIMESTAMPTZ, '6aacf02101ea2acf26d96c255fee440e8013e061f15f889e7d9084ff3dd0c17d'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'Este profesor es una falta de respeto para la carrera y sus estudiantes, le encanta jugar de duro solo para que uno pierda el curso y la salud mental, no se me ocurre otra razón. Mi consejo: si no pudo meter con otro profe y le tocó con Torres y por ahí de semana 10 quiere dejar todo tirado hágalo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-07-21T00:00:00+00:00'::TIMESTAMPTZ, '2528a94d91b20ccb58ceb20adedf40b9f72e9e6f259eeaed21abb1e35183e1fd'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Un profe bastante duro, tienes que preguntar bastante para hacer las cosas justo como él quiere y en este caso también bastante paciencia porque el profe podía durar varios días para responder el foro. El curso es interesante, pero hubiese preferido aprenderlo con alguien más.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2022-06-25T00:00:00+00:00'::TIMESTAMPTZ, '0739f2c96c455dbab428f794ccb24d63a6283332ceb38ade4746fc9014a092c1'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'El peor profesor de todo el TEC. El pero curso que he llevado en toda la carrera. Una mala persona sin ningún interés en ayudar al estudiante. No le gusta explicar. Evítelo, es mejor atrasarse que llevar una materia con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'edeaeca10adb17c8c6c162b6c7be5db95304fd875065de7e7f37ba32d9183a02'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Un inepto, cree que es un genio por dominar materia que viene dando desde hace 20 años. Humilla a los estudiantes y se cree la última coca del desierto, alguien despierte a este señor y dígale que no está trabajando en la NASA ni mucho menos, solo es un profesor de una U de un país tercermundista.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'acd78fbb8023319fe3943ad88cd59925164bf979410d2df6a456c1e8eff4152e'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Mejor atrasarse en la carrera que llevar con este mae, es la peor escoria de los profes del tec'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-04-21T00:00:00+00:00'::TIMESTAMPTZ, '67d844e921ed7ce93e513b9bdfcc1a29140518e5f3b20f7b4936639c7fd09643'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Si buscas un profesor que tenga una completa falta de respeto por la enseñanza y los estudiantes, este es tu profesor, de lo contrario evítalo a toda costa.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-04-12T00:00:00+00:00'::TIMESTAMPTZ, '627469d9b920044a445654c027ba04a3c4a71a8f60901ea963400271b2a1ece1'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'El pero profesor de la carrera de Ing. en Computación. No da clases, no explica nada y pone proyectos ultradifíciles. Evítelo a toda costa.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-03-04T00:00:00+00:00'::TIMESTAMPTZ, '405b4505a77eea0bab0d31b285e16d0be0f83d0fad497be716fdd266be2f0b58'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Torres es todo la malo que un profesor puede tener, que asco de tipo'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-03-01T00:00:00+00:00'::TIMESTAMPTZ, 'bb73fc23f39545726c2f95681a3dba54cdd3fe88134c46dfb0382b5ad32bffc7'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Si ud ha tenido un profesor malo pues agarrelo, multipliquelo por 10 y el resultado será Francisco Torres.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-02-03T00:00:00+00:00'::TIMESTAMPTZ, '41501fde2ff9eaa40296464e6e35d11f2b349a033ad62bf154669a4bf90e70c4'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Este mal dado a luz, tiene demasiada soberbia es un mediocre "profesional" con aires de grandeza. No se embarque'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2022-02-01T00:00:00+00:00'::TIMESTAMPTZ, '60ead85831aca96bb64dec777fed680a4c31389d517d21a7ddab126d536225cf'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Después de Kirstein creí que no había peor profesor en esta universidad hasta que llegó Torres a dar cátedra de cómo NO debe ser un profesor. Me atrevo a decir que este señor busca la manera de quedarlo a uno sólo porque el mae siente que nadie merece pasar un curso de él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil']::TEXT[], '2022-01-12T00:00:00+00:00'::TIMESTAMPTZ, '0b781cbbd2dc6376a188c593bff18e9cb12ba6c1f666c6a92d8fa4dd7ab48f2c'::TEXT, ARRAY[1430]::BIGINT[]),
    (291::BIGINT, 'Este hp literal se robó el salario este semestre, no dió clases, no brindó ayuda para nada, los trabajos son sacados de libros viejos, todo lo revisa el asistente que baja puntos hasta por respirar. Pero para poner correos amenazantes para que uno no copie en los exámenes sí parecía muy atento....'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-16T00:00:00+00:00'::TIMESTAMPTZ, 'b88db66c6c68367514d7a39cace134425095545f86cbe4391044538f6aacf9f8'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, '"Mejor pasese a la Ulacit" puso en uno de los pdfs cómo "mensaje de error". La soberbia de este mae es increíble y yo sólo pienso "si se siente tan pichudo por su título del TEC que hace aquí y xq no está en alguna transnacional ganándose un montón de plata?" Un mediocre que se siente Dios'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-05T00:00:00+00:00'::TIMESTAMPTZ, 'c11540023544618da9700ad0209c026f0c7cf21357ce5f5f4e563058cf94fb49'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Nefasto, el "profesor" es un incompetente que ni clases da y toda la materia se basa en libros de hace 30 años. Los proyectos son ambiguos y si uno quiere explicaciones simplemente se molesta, hace un comentario despectivo y no responde. Le falta madurez a este señor'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-10-31T00:00:00+00:00'::TIMESTAMPTZ, 'bbcf9d0f327a4ff8a163c92de929ed28265a9c04e20b949539f89f936c1d0d24'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Sin lugar a dudas el peor profesor con el que me he topado en mi vida. El material que usa en clases está súper desactualizado, no tolera que se le corrija cuando se equivoca, sus criterios de evaluación son atojadizos y nunca explica porqué rebaja puntos. Es todo lo que un profesor no debe ser.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2021-10-30T00:00:00+00:00'::TIMESTAMPTZ, '299d8b73b95003c655d4cb8152732795a6c50755a5c8af1b66d4c4e991c19827'::TEXT, ARRAY[337]::BIGINT[]),
    (291::BIGINT, 'No prepara al estudiante en nada pero eso sí, los proyectos son de lo más exigente. Negligente con su trabajo, nunca está disponible para una consulta y ni siquiera da clases, todas las semanas hay tareas pesadísimas. Prefiero atrasarme en la carrera que volver a llevar con este ser.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Muchas tareas']::TEXT[], '2021-10-09T00:00:00+00:00'::TIMESTAMPTZ, '9a06732b35ae5b3b698da04224cda0dc6b1fd8f42187af247dd385945a6e0a2f'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'No sé ni cómo calificarlo porque a estas alturas del semestre ni se ha presentado, solo se comunica por correos amenazantes y jamás responde dudas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-10-07T00:00:00+00:00'::TIMESTAMPTZ, '38fe3d6bee5039eb1378b80c809c66b23ada10a9216c252822168dd4aaac41b5'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Puras tareas inútiles, lecturas de libros viejos, no tuvo ni la decencia de presentarse el primer día, nunca nos ha dado una clase, de 24 que éramos ya 13 retiraron el curso, usa el foro prehistórico cómo dijeron abajo que es un asco, todo son amenazas y con nada se le queda bien.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-10-05T00:00:00+00:00'::TIMESTAMPTZ, '76ffeab6c1fae8c2440b99a66b5c4db854ba196919cd728a0102c7d430a79a00'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Se supone que el curso es de 3 créditos y se siente cómo de 10. Para todo hay que usar un mierdoso foro que ni se entiende, los trabajos engorrosos y para todo lanza amenazas de "poner un 0"'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-09-29T00:00:00+00:00'::TIMESTAMPTZ, '2df7699965a24a2c8cdff46ed7400678b166245bcac157f675009003b05040fa'::TEXT, ARRAY[1430]::BIGINT[]),
    (291::BIGINT, 'De dónde saca la gente que este señor es un "genio"? Yo solo veo un pedante engreído que se quedó en el siglo pasado y nunca se actualizó, sus clases son una perdida de tiempo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-09-28T00:00:00+00:00'::TIMESTAMPTZ, '1adaf6fd9dc24f70c3fe1b4b0441e29dcdc7e91cc7cb6e54805330ff998b24ae'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Kirstein versión sabemás'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-09-22T00:00:00+00:00'::TIMESTAMPTZ, '0df09ace1b60d07f1c0ccc4c1d460b0a0bab58700e343e3355fc587631a493af'::TEXT, ARRAY[4759]::BIGINT[]),
    (291::BIGINT, 'Con la virtualidad se le cayó el título de ingeniero, se lo comen las tecnologías nuevas y la materia que manda de tarea (no da clases, todo es asincrónico) es sacada de libros viejos. Este mae a ud no lo preparada para nada, sólo lo jode, meta con cualquier otro.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-09-09T00:00:00+00:00'::TIMESTAMPTZ, '9bfa628476c1aa109941068a3406e7171a2b592688d1603b8e948e4a528d0492'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Un profesor 100% académico, de esos que nunca salieron del ambiente de la U y no te van a enseñar nada útil para el mundo real por lo tanto los trabajos son una parida porque "hay que cumplir con el sello TEC" que es dejar tareas a montones hasta que el estudiante no pueda más'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-27T00:00:00+00:00'::TIMESTAMPTZ, '1e7e5eeddbdea90819d79dac06a7e4eed9e43d1e328ad0cae47a44056482f222'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Curso UNED sin tutorias. Usa el foro prehistórico de la escuela. No da clases virtuales y si el grupo las pide pone condiciones. No prepara las presentaciones, comparte apuntes de estudiantes de otros semstres.Tareas son leer y hacer ejercicios de capitulos (no las plantea el). Peor que Kirstein!!'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Muchos proyectos grupales']::TEXT[], '2021-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'ba485b54d3f5b04ebc01da8edbeb254e000706d2518115cb8fa53c72bf8a858a'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'No es una sorpresa con Torres que es un genio, pero que sigue teniendo el EGO muy alto. Es el Kirstein de San José, por favor meta con cualquier otro profesor antes que con este señor. Y sino le queda de otra por favor nunca meta doble con él, por si bienestar académico y salud mental.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'a70e22690702a2943c66089343b492ece3512dfd6762c09c90c74cb115598268'::TEXT, ARRAY[1054, 1151]::BIGINT[]),
    (291::BIGINT, 'Wow que montón de buenos comentarios, muy sospechoso porque todo el semestre nos quejamos de lo pésimo que era este profesor además de que abundaron los quedados y las malas notas, pero en esta página hace parecer que era facílisimo pasar con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-02T00:00:00+00:00'::TIMESTAMPTZ, '49b618bed5f29e905f7d1c03da687bda44e7b4c53cfa7903f72011e476a67fb0'::TEXT, ARRAY[1054, 1130]::BIGINT[]),
    (291::BIGINT, 'Puso un foro supuestamente para comunicarse y aún así cuando preguntábamos en el nunca respondía, ese curso fue un absoluto desastre'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Pocos exámenes', 'Exámenes retadores']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'cfc0143bde8bc72cf298327e596d6df841784245559d4728d85c2b5410ac1802'::TEXT, ARRAY[1430]::BIGINT[]),
    (291::BIGINT, 'El curso se pasa con conectarse, super clara la materia y super accesibles las rúbricas. De los profes que nejor explican y mejor evalúan'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2021-06-28T00:00:00+00:00'::TIMESTAMPTZ, '69e56705e0f21996c46d57fc7982eb409192cfd2e8212d793d6c4204f928eb17'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Torres es muy buen profe, deja muchas tareas pero por eso es facil la materia. Los examenes no son faciles sin embargo tampoco es necesario sacarse buena nota en ellos para pasar, si le va bien en los proyectos y tareas es suficiente. Explica muy claro y responde dudas por correo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Da crédito extra']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, '0b7bc95aa598110100cac1e1cff340c0175d947a47f413f0b50116c91db21076'::TEXT, ARRAY[1035, 1151, 1054]::BIGINT[]),
    (291::BIGINT, 'Había oido mucho de él. Pero ahóra que lleve un curso no me gustó. Creo que da pésimas clases virtuales y es muy injusto para calificar.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2021-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'ed4c9f41c24625d3cf21f561cb7e8632a096b6a959429bd21619431bd7381c76'::TEXT, ARRAY[1017]::BIGINT[]),
    (291::BIGINT, 'Amé llevar FOC con este profesor, siempre le entendí a la primera por que explica muy bien eso si, deja muuucha tarea y algunas son largas pero si hace todo y se organiza pasa sobrado. SUPER recomendado.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-11T00:00:00+00:00'::TIMESTAMPTZ, '1b9b2e7f0ff891d87beb436e2a5d757e9f72b822f7335d97dd0910a3db7c7b84'::TEXT, ARRAY[1017]::BIGINT[]),
    (291::BIGINT, 'Muy buen profesor, le entendí muy bien ya que siempre busca el método más fácil. Deja muchos trabajos, pero si los hacen todos va bien. Lo recomiendo :)'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2020-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'c21852e0db5eec42b4dfeab5ee3ee362587cb16ce874facb4d67b57e1138f56a'::TEXT, ARRAY[1017]::BIGINT[]),
    (291::BIGINT, 'Super profe!, es matado, deja muchos trabajos pero realizables, explica muy bien y siempre le entendi a la primera. Super recomendado.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Da crédito extra']::TEXT[], '2020-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'e82884155e2b6fcb83496103431f0067127d842925bdd120cd09c4c7908f00b7'::TEXT, ARRAY[1017]::BIGINT[]),
    (291::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'a5f02961c57203d69d2057e41aeecde96273136fdbaa9687000cecad54e5e6b7'::TEXT, ARRAY[1151]::BIGINT[]),
    (291::BIGINT, 'Ordenado con las evaluaciones, hace quiz todas las semanas pero se saca estudiando poco. Clases de presentaciones, un poco aburridas pero el profe les pone mucho humor. El curso es duro pero se aprende mucho con él.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Aspectos de calificación claros']::TEXT[], '2020-02-05T00:00:00+00:00'::TIMESTAMPTZ, '296c427192df2332c9709bc84cc95b85595332545d7e22b2a28924d3b7ade973'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'Es un excelente profe, enseña muy bien y si uno no entiende algo él se lo explica hasta que entienda, hace quices todas las semanas pero si entendió la clase anterior al quiz de fijo lo pasa. Si usted no pasa un curso con él es su culpa, porque es excelente como profe.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-26T00:00:00+00:00'::TIMESTAMPTZ, '225cf34b54674d0f6f08a8c3306b3ecb6f19f9fbb98dd988064ec171cb425e78'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'No es ni mal profesor, ni buen profesor. Complica mucho cursos relativamente faciles. No recomiendo llevar con el si tiene otra opcion, si le da el primer strike no vuelva a clases que ya perdio el curso, hay dias en los que esta de buen humor y otros que esta de mal humor, proyectos dificiles.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, '2180df8d414845d9194a29d6647cd74143c3b3004afe942c12f7d03ecd6c6cd2'::TEXT, ARRAY[1017]::BIGINT[]),
    (291::BIGINT, 'Uno aprende bastante en el curso aunque sea mucha materia. Hace quices todas las semanas, pero son pasables si se atiende a clases.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-14T00:00:00+00:00'::TIMESTAMPTZ, '4376438f80a9f9ddf4c2de9b2a887c584bf1b241d7030139796d706f29d0bb23'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'Muy malas explicaciones para hacer la tarea y es irrespetuoso con los estudiantes'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-10-25T00:00:00+00:00'::TIMESTAMPTZ, 'b1944e048f44bf16eaa53e5049aa64481c0210d81a71ef6e98f3a0fc1789299e'::TEXT, ARRAY[1121]::BIGINT[]),
    (291::BIGINT, 'No da rúbricas, evalúa lo que le da la gana Los exámenes son muy duros y cambia de opinión a cada rato'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2019-08-28T00:00:00+00:00'::TIMESTAMPTZ, '2666170a2793a4e94ff086e06fd38c7bb040fe4f31e840686d708014830aff0d'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'Muchas evaluacines y no se sabe cómo las va a evaluar. Me pareció un poco irrespetuoso hacia los estudiantes.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchos exámenes']::TEXT[], '2019-08-22T00:00:00+00:00'::TIMESTAMPTZ, '970ee822ddc21e5905995c87b1336b63bbed24f890c7b7a1cb6cd08b8af44c54'::TEXT, ARRAY[1121]::BIGINT[]),
    (291::BIGINT, 'Evaluaciones hay muchas. Las instrucciones de los proyectos 0 claras. Califica más de lo que viene en las especificaciones (Ej: animaciones gráficas cuando no se pidió). 0 respeto hacia el estudiante y hacia la mujer. Tiene una personalidad grotesca. No evalúa reclamos ni tiene horas de consulta.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2019-08-12T00:00:00+00:00'::TIMESTAMPTZ, '71942a4788ec1c0a2ee0f163c957dd80d98e91f56a103badb0082c7b2e8bd176'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'Explica bastante bien, si no entiende le vuelve a explicar. Proyectos y tareas programadas elaboradas. Los exámenes son difíciles (un 6 de 1-10).'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2019-07-26T00:00:00+00:00'::TIMESTAMPTZ, '47b092e3f4a04a4477a05bb8dcf5e87ff8d5885551b4a26b8247e06f8cafdcd0'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'Puro bla, bla, bla y nada de contenido. Es de esos profes que creen que saben mucho pero solo hace los ejercicios sencillos. Lo difícil lo deja para las tareas.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2018-09-28T00:00:00+00:00'::TIMESTAMPTZ, '2821effeada1651e23ea1c23e3ba8cb3630e978bd5698e58f50e19731e7caf1b'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Las tareas son largas y tediosas, pro la materia en clase es muy buena y acorde con la evaluacion.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2018-07-16T00:00:00+00:00'::TIMESTAMPTZ, '959bc1cd03205aef3fef50d666ca275888b17ecee84f76791b6505cb030bd98a'::TEXT, ARRAY[1017]::BIGINT[]),
    (291::BIGINT, 'No me gustó el curso. En clases hace ejemplos muy sencillos, pero las tareas son super difíciles. Nada que ver con lo visto en clase.'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2018-07-16T00:00:00+00:00'::TIMESTAMPTZ, '677ae207e33fdf0979369ffc4e9739e3616303650e90015b6aefd43d644a6878'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'El profe que mejor prepara sus clases, examenes y proyectos. Todo lo tiene demasiado medido. Usted en todo momento sabe que nota lleva en todo. Explica muy bien. El curso es rudo, pero se aprende demasiado. Hay que ponerle pero para eso estamos en el TEC.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '406ce154735280233e69395feb70c4c21ca9aae423e435135fa056dd67651f10'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Un gran profe donde la materia es fácil de entender, y sus clases no son aburridas. Los examenes son muy prácticos, hay que ponerle. Los proyectos, en compi, son difíciles, en IO no tanto. Es muy ameno e incluso se puede aprender de él cosas más allá del curso, como libros y otros temas.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-21T00:00:00+00:00'::TIMESTAMPTZ, '6e200bda64988472d90a8933393ae8a117bdbde1c3279359a244fc5e69fd987b'::TEXT, ARRAY[1151]::BIGINT[]),
    (291::BIGINT, 'Es muy buen profe, en lo único que se puede perder puntos es en los exámenes que son dificilillos, lo demás es fácil y lograble.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'f76f2bd546dd6628e13f8517408f6214bd5e1b13cdafd6e8e63d0dd339e8ecec'::TEXT, ARRAY[1035]::BIGINT[]),
    (291::BIGINT, 'Excelente profesor, todo queda muy claro.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2018-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'cb127f26639c72cdcbd0e65d65f26a21bdb58ad2f9ceef7e2bcfa54b21dcb1d0'::TEXT, ARRAY[1017]::BIGINT[]),
    (291::BIGINT, 'Había odio mucho de este profe, pero la verdad no me gustó. Solo habla de sus conferencias y viajes pero no prepara bien las clases.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2017-11-15T00:00:00+00:00'::TIMESTAMPTZ, '61ed850cc4d8b1944f3dcb21e88d3cf1b2a6722275ddb6763a96199b3a773a2b'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Excelente profesor. Se nota que le gusta enseñar, la materia aunque sean puras presentaciones no es un karaoke, osea él sabe de lo que habla e inclusive brinda más información. Los examenes son pasables, los quices también. Los proyectos fue lo más difícil, rudillos. Lo recomiendo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '88a8ad9592933b52c030d653853e6fe972544cc2c3a55dec5dd6b482b76875b8'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Es un curso más teórico que práctico, donde se va aprender muchas cosas de biólogia. Los exámenes son de marque con X y permite el uso de un "forro" en ellos. Si se llevo IO con él la materia programada que se ve es muy fácil de asimilar.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '76f6e2190ab282f676550bbefc0b8842620dc7ebe1f0e7be8c34b657daa5b392'::TEXT, ARRAY[1121]::BIGINT[]),
    (291::BIGINT, 'Las clases son divertidas, los exámenes de dificultad media. Muchas tareas y algunas nada que ver con la materia. Los proyectos son medio complicados, y hay que estar atento ya que los califica de manera subjetiva, sin guiarse por lo que dice sus especificaciones. Además, quices todas las semanas.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Clases excelentes']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c53d47f79f055fcd609cf8c8cba72522e3dfc621ca17397eb4209819d83fafb2'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Un profesor sin mística. Los trabajos son muy largos y tienen poca relación con la materia que da en clase. Me parece que favorece a unos más que otros de manera subjetiva.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2017-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'a05ce14e6aee9d9e2054416433f8dbf9c1e0d341bf516362dd6efbb0c0f3edf5'::TEXT, ARRAY[1151]::BIGINT[]),
    (291::BIGINT, 'Explica muy bien la materia y es divertido por lo que es fácil entender sin embargó los proyectos no van con lo que se está viendo en la clase en ese momento así que cuestan bastante porque hay que investigar por aparte ya que no explica mucho.Hay que esforzarse bastante pero es pasable y se aprende'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '06ad12916b3d49d6600112e96d1e14d5e63fe5bb11570a116542df757d0f81be'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'La persona que dijo que el profe no tiene experiencia profesional está hablando paja. Revise el curriculum del Dr. Torres antes de hablar. Una recomendación de él te consigue campo en universidades del exterior y en casi cualquier empresa nacional. Debieramos agradecer que prefiera darnos clases.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-04-07T00:00:00+00:00'::TIMESTAMPTZ, '6a457c9e8707cd0393cee787a5b8490c03f5683c32258884f87e83b36e01a9f7'::TEXT, ARRAY[1151]::BIGINT[]),
    (291::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2017-02-03T00:00:00+00:00'::TIMESTAMPTZ, '64b4132b2306f079c4fc3c0cd7aac73832832ed5f981b41f414da09a10021220'::TEXT, ARRAY[1151]::BIGINT[]),
    (291::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases excelentes']::TEXT[], '2017-01-29T00:00:00+00:00'::TIMESTAMPTZ, '32a13b33a8cd46aea979d2cf09694bbff82ad56dbc2869ff357ede3c990d319c'::TEXT, ARRAY[337]::BIGINT[]),
    (291::BIGINT, 'La realidad es que es un profesor sobrevalorado, tiene seguidores, lo cual no es malo, pero objetivamente es un académico sin experiencia profesional, juega de místico y gran cosa, pero su trabajo lo hace a media maquina'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '93ca46011c00da6b63432a35d51da4017c213650e9b5db8ead3d7a455be0f5f9'::TEXT, ARRAY[1130]::BIGINT[]),
    (291::BIGINT, 'Excelente profesor. A pesar de que Computer Graphics es su hobbie, el material que brinda es muy claro y lo explica muy bien. Clases excelentes. Curso de dificultad media. No descuidar proyectos o exámenes.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-10T00:00:00+00:00'::TIMESTAMPTZ, 'cd0c0b083e49a68978899c50a4d34e413f14b719fe26ed77dc3ef96d411c543c'::TEXT, ARRAY[1130]::BIGINT[]),
    (291::BIGINT, 'Excelente profesor. Si quieres llevarla suave o aprender apenas lo necesario para pasar, busca otro profesor. Si quieres aprender y trabajar duro para pasar el curso, ya lo encontraste.'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-16T00:00:00+00:00'::TIMESTAMPTZ, '71935cf14b1c7ee1bf58b6d6b3bc800093bfa452c47b9e4e26f5fd76720b306d'::TEXT, ARRAY[337]::BIGINT[]),
    (291::BIGINT, 'El comentario de abajo es verdadero. Es un profe malo con poco interés en ayudar a sus alumnos.'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Exámenes retadores']::TEXT[], '2016-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'a3fef2bfbdbd2dcbff446c335f8532f6e58ecd539e76bc8f3e38a2555ad40230'::TEXT, ARRAY[1151]::BIGINT[]),
    (291::BIGINT, 'El comentario de abajo es mentira, es un excelente profesor sus evaluaciones son justas y explica muy bien, si Torres le parece malo no me quiero imaginar lo que va a pensar más adelante en la carrera de otros profes.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2016-10-29T00:00:00+00:00'::TIMESTAMPTZ, '2b8ffa99a2cdd334164aec488e40b3064727e230bdf56f88230b477c15cf0815'::TEXT, ARRAY[1151]::BIGINT[]),
    (291::BIGINT, 'Un profe malo, que aparenta ser bueno. Lo que enseña en clase no tiene relación con lo que evalúa. Las evaluaciones son su fin, no enseñar.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2016-10-06T00:00:00+00:00'::TIMESTAMPTZ, '7ae6e263574a5882c0d5924e038c9651bd552561c1e130f575c690be0e4f3213'::TEXT, ARRAY[1017]::BIGINT[]),
    (291::BIGINT, 'Excelente profesor, explica super claro te ayuda en la medida de lo posible, y se aprende super bien.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'bbaf2948a4a76e220da08cd8c74eafbb86c3b69313b87bf928f2a379c32ac1f5'::TEXT, ARRAY[1054]::BIGINT[]),
    (291::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases excelentes']::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'c3c8bddcc1368d9170993b31ce7d3a4d1e7626eb8b5cdc9f2a6fc0c6fd3eec1e'::TEXT, ARRAY[1017]::BIGINT[]),
