    (291::BIGINT, 'El mejor profe que he tenido hasta el momento. Hay que ir a TODAS las clases y aunque es puntual tanto a la hora de entrar como a la hora de salir y hay que tomar bastantes apuntes. Las clases son dinámicas y son cursos a los cuales se disfruta asistir'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '1570ce82423b3fab7de8185a2ecbb2c94809d3e9078792ee3b1bd5651878bd04'::TEXT, ARRAY[1151]::BIGINT[]),
    (291::BIGINT, 'El mejor profesor de la carrera de Ing. en Computación. Prepara muy bien el material y sabe mucho'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '729d986d8ecfc8675ee38f11fde276bf424abfa5dc1c5147bbcf93514b21765f'::TEXT, ARRAY[1151]::BIGINT[]),
    (291::BIGINT, 'Un modelo a seguir como profesor, excelente'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'e54bb7fb8b7e6252e3ae67516132cb9eb0431e84c9ee46b1cc0de9cd62204c3c'::TEXT, ARRAY[337]::BIGINT[]),
    (291::BIGINT, 'Excelente profesor! Explica muy bien! Las evaluaciones van acorde a la materia'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-14T00:00:00+00:00'::TIMESTAMPTZ, 'f26222edd904127d062b6560b9a047ea8f00e8702572867a13f56c1cc7ea47b0'::TEXT, ARRAY[1121]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
